import React, { useState, useEffect } from 'react';
import API from '../utils/api';
import toast from 'react-hot-toast';

const Payments = () => {
  const [payments, setPayments] = useState([]);
  const [summary, setSummary] = useState(null);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [customers, setCustomers] = useState([]);
  const [formData, setFormData] = useState({
    customerId: '',
    amount: '',
    billingMonth: '',
    method: 'Cash',
    notes: '',
  });

  useEffect(() => {
    loadPayments();
    loadSummary();
    loadCustomers();
  }, []);

  const loadPayments = async () => {
    try {
      const res = await API.get('/payments');
      setPayments(res.data.data);
    } catch (error) {
      toast.error('Failed to load payments');
      console.error('Error:', error);
    }
  };

  const loadSummary = async () => {
    try {
      const res = await API.get('/payments/summary');
      setSummary(res.data.data);
    } catch (error) {
      console.error('Error loading summary:', error);
    }
  };

  const loadCustomers = async () => {
    try {
      const res = await API.get('/customers');
      setCustomers(res.data.data);
    } catch (error) {
      console.error('Error loading customers:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await API.post('/payments', formData);
      toast.success('Payment recorded successfully!');
      setShowModal(false);
      setFormData({ customerId: '', amount: '', billingMonth: '', method: 'Cash', notes: '' });
      loadPayments();
      loadSummary();
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to record payment');
      console.error('Error:', error);
    }
  };

  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

  if (loading) {
    return <div className="loading">Loading...</div>;
  }

  return (
    <div>
      <div style={styles.header}>
        <h2 style={styles.pageTitle}>Payments</h2>
        <button style={styles.addBtn} onClick={() => setShowModal(true)}>
          ➕ Record Payment
        </button>
      </div>

      {/* Summary Cards */}
      {summary && (
        <div style={styles.summaryGrid}>
          <div style={styles.summaryCard}>
            <div style={styles.summaryLabel}>Total Collected</div>
            <div style={styles.summaryValue}>PKR {summary.totalCollected?.toLocaleString() || 0}</div>
          </div>
          <div style={styles.summaryCard}>
            <div style={styles.summaryLabel}>This Month</div>
            <div style={styles.summaryValue}>PKR {summary.monthlyCollection?.toLocaleString() || 0}</div>
          </div>
          <div style={styles.summaryCard}>
            <div style={styles.summaryLabel}>Transactions</div>
            <div style={styles.summaryValue}>{summary.totalTransactions || 0}</div>
          </div>
          <div style={styles.summaryCard}>
            <div style={styles.summaryLabel}>This Month Transactions</div>
            <div style={styles.summaryValue}>{summary.monthlyTransactions || 0}</div>
          </div>
        </div>
      )}

      {/* Payments Table */}
      <div style={styles.tableContainer}>
        <table style={styles.table}>
          <thead>
            <tr>
              <th>Receipt #</th>
              <th>Date</th>
              <th>Customer ID</th>
              <th>Customer Name</th>
              <th>Amount</th>
              <th>Month</th>
              <th>Method</th>
              <th>Notes</th>
            </tr>
          </thead>
          <tbody>
            {payments.length === 0 ? (
              <tr><td colSpan="8" style={{ textAlign: 'center', padding: '30px', color: '#6b7f99' }}>No payments recorded</td></tr>
            ) : (
              payments.map((p) => (
                <tr key={p._id}>
                  <td><strong>{p.receiptNumber}</strong></td>
                  <td>{new Date(p.date).toLocaleDateString()}</td>
                  <td>{p.customerId}</td>
                  <td>{p.customerName}</td>
                  <td style={{ color: '#28a745', fontWeight: '600' }}>PKR {p.amount.toLocaleString()}</td>
                  <td>{p.billingMonth} {p.billingYear}</td>
                  <td><span style={{ ...styles.methodBadge }}>{p.method}</span></td>
                  <td style={{ color: '#6b7f99', fontSize: '12px' }}>{p.notes || '—'}</td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Modal */}
      {showModal && (
        <div style={styles.modalOverlay} onClick={() => setShowModal(false)}>
          <div style={styles.modal} onClick={(e) => e.stopPropagation()}>
            <h3 style={styles.modalTitle}>💰 Record Payment</h3>
            <form onSubmit={handleSubmit}>
              <div style={styles.formGroup}>
                <label style={styles.label}>Select Customer *</label>
                <select
                  name="customerId"
                  value={formData.customerId}
                  onChange={handleInputChange}
                  style={styles.input}
                  required
                >
                  <option value="">Select a customer...</option>
                  {customers.map((c) => (
                    <option key={c._id} value={c.customerId}>
                      {c.name} ({c.customerId})
                    </option>
                  ))}
                </select>
              </div>
              <div style={styles.formGroup}>
                <label style={styles.label}>Amount (PKR) *</label>
                <input
                  type="number"
                  name="amount"
                  value={formData.amount}
                  onChange={handleInputChange}
                  style={styles.input}
                  required
                  min="1"
                />
              </div>
              <div style={styles.formGroup}>
                <label style={styles.label}>Billing Month *</label>
                <select
                  name="billingMonth"
                  value={formData.billingMonth}
                  onChange={handleInputChange}
                  style={styles.input}
                  required
                >
                  <option value="">Select month...</option>
                  {months.map((m) => (
                    <option key={m} value={m}>{m}</option>
                  ))}
                </select>
              </div>
              <div style={styles.formGroup}>
                <label style={styles.label}>Payment Method</label>
                <select
                  name="method"
                  value={formData.method}
                  onChange={handleInputChange}
                  style={styles.input}
                >
                  <option value="Cash">Cash</option>
                  <option value="Bank Transfer">Bank Transfer</option>
                  <option value="Easypaisa">Easypaisa</option>
                  <option value="JazzCash">JazzCash</option>
                  <option value="Other">Other</option>
                </select>
              </div>
              <div style={styles.formGroup}>
                <label style={styles.label}>Notes</label>
                <input
                  type="text"
                  name="notes"
                  value={formData.notes}
                  onChange={handleInputChange}
                  style={styles.input}
                  placeholder="Optional notes..."
                />
              </div>
              <div style={styles.modalActions}>
                <button type="button" style={styles.cancelBtn} onClick={() => setShowModal(false)}>Cancel</button>
                <button type="submit" style={styles.saveBtn}>Record Payment</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

const styles = {
  header: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '20px',
    flexWrap: 'wrap',
    gap: '12px',
  },
  pageTitle: {
    fontSize: '22px',
    fontWeight: '700',
    color: '#1a2a3a',
    margin: 0,
  },
  addBtn: {
    padding: '10px 24px',
    background: '#28a745',
    color: 'white',
    border: 'none',
    borderRadius: '10px',
    fontSize: '14px',
    fontWeight: '600',
    cursor: 'pointer',
    transition: '0.2s',
  },
  summaryGrid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))',
    gap: '16px',
    marginBottom: '24px',
  },
  summaryCard: {
    background: 'white',
    padding: '16px 20px',
    borderRadius: '12px',
    border: '1px solid #e9eef4',
  },
  summaryLabel: {
    fontSize: '12px',
    color: '#6b7f99',
    textTransform: 'uppercase',
    fontWeight: '500',
  },
  summaryValue: {
    fontSize: '24px',
    fontWeight: '700',
    color: '#1a2a3a',
    marginTop: '4px',
  },
  tableContainer: {
    background: 'white',
    borderRadius: '12px',
    border: '1px solid #e9eef4',
    overflow: 'hidden',
  },
  table: {
    width: '100%',
    borderCollapse: 'collapse',
    fontSize: '13px',
  },
  methodBadge: {
    display: 'inline-block',
    padding: '2px 10px',
    borderRadius: '12px',
    background: '#e9eef4',
    fontSize: '11px',
    fontWeight: '500',
  },
  modalOverlay: {
    position: 'fixed',
    inset: 0,
    background: 'rgba(0,0,0,0.5)',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    zIndex: 1000,
    backdropFilter: 'blur(4px)',
  },
  modal: {
    background: 'white',
    borderRadius: '20px',
    padding: '32px',
    width: '500px',
    maxWidth: '95%',
    maxHeight: '90vh',
    overflow: 'auto',
  },
  modalTitle: {
    fontSize: '20px',
    marginBottom: '20px',
    color: '#1a2a3a',
  },
  formGroup: {
    marginBottom: '16px',
  },
  label: {
    fontWeight: '500',
    marginBottom: '4px',
    fontSize: '14px',
    color: '#1a2a3a',
    display: 'block',
  },
  input: {
    width: '100%',
    padding: '10px 14px',
    border: '2px solid #e2eaf2',
    borderRadius: '10px',
    fontSize: '14px',
    boxSizing: 'border-box',
  },
  modalActions: {
    display: 'flex',
    gap: '12px',
    marginTop: '20px',
    justifyContent: 'flex-end',
  },
  cancelBtn: {
    padding: '10px 24px',
    background: '#e9eef4',
    border: 'none',
    borderRadius: '10px',
    fontSize: '14px',
    fontWeight: '500',
    cursor: 'pointer',
  },
  saveBtn: {
    padding: '10px 24px',
    background: '#28a745',
    color: 'white',
    border: 'none',
    borderRadius: '10px',
    fontSize: '14px',
    fontWeight: '600',
    cursor: 'pointer',
  },
};

export default Payments;
